function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50 * Math.cos(t), H/2 - 50 + 20 * Math.sin(t), 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.cos(t), H/2 - 50 + 20 * Math.sin(t), 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // tree
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2, H - 150 - 50 * Math.sin(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2, H - 150 - 50 * Math.sin(t), 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
